import sys
import os
import hashlib
import re
from typing import Dict, Any

def compute_check(input_bytes: bytes, secret: str) -> str:
    combined = input_bytes + secret.encode()
    return hashlib.sha256(combined).hexdigest().lower()

def parse_check_line(line: str) -> tuple:
    match = re.match(r'check=([a-f0-9]+)', line.strip())
    if not match:
        raise ValueError("Invalid check line format")
    return match.group(1), line

def evaluate_recipe_file(file_path: str) -> None:
    with open(file_path, 'r') as f:
        lines = f.readlines()

    check_line = lines[0].strip()
    computed_check, _ = parse_check_line(check_line)
    secret = os.getenv('RECIPE_SECRET', '')
    if not secret:
        raise ValueError("RECIPE_SECRET environment variable not set")

    body_bytes = b''.join(lines[1:]).encode()
    expected_check = parse_check_line(check_line)[0]
    computed_check_value = compute_check(body_bytes, secret)

    if computed_check_value != expected_check:
        sys.stderr.write('ERROR: check mismatch\n')
        sys.exit(1)

    variables: Dict[str, Any] = {}
    for line_num, line in enumerate(lines[1:], 1):
        stripped_line = line.strip()
        if not stripped_line:
            continue
        match = re.match(r'([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.+)', stripped_line)
        if not match:
            sys.stderr.write(f'ERROR line {line_num}: invalid syntax\n')
            sys.exit(1)
        name, expr = match.groups()
        try:
            value = eval(expr, {}, variables)
            sys.stdout.write(f'{name}={value}\n')
            sys.stderr.write(f'OK {name}={value}\n')
            variables[name] = value
        except Exception as e:
            sys.stderr.write(f'ERROR line {line_num}: {str(e)}\n')
            sys.exit(1)

def main():
    if len(sys.argv) == 2 and sys.argv[1] == '--make-check':
        input_bytes = sys.stdin.buffer.read()
        secret = os.getenv('RECIPE_SECRET', '')
        if not secret:
            sys.stderr.write('RECIPE_SECRET environment variable not set\n')
            sys.exit(1)
        sys.stdout.write(f'check={compute_check(input_bytes, secret)}\n')
    else:
        if len(sys.argv) != 2:
            sys.stderr.write('Usage: python recipe_eval.py <path> or python recipe_eval.py --make-check\n')
            sys.exit(1)
        file_path = sys.argv[1]
        try:
            evaluate_recipe_file(file_path)
        except Exception as e:
            sys.stderr.write(f'ERROR: {str(e)}\n')
            sys.exit(1)

if __name__ == '__main__':
    main()

import sys
import os
import hashlib
import ast
import re

def compute_check(input_bytes, salt):
    combined = input_bytes + salt.encode()
    return hashlib.sha256(combined).hexdigest().lower()

def parse_check_line(line):
    match = re.match(r'check=([a-f0-9]+)', line.strip())
    if not match:
        raise ValueError("Invalid check line format")
    return match.group(1)

def evaluate_body(body_bytes, salt):
    lines = body_bytes.decode('utf-8').splitlines()
    if not lines:
        return

    namespace = {}
    for i, line in enumerate(lines[1:], 2):
        try:
            name, expr = line.split('=', 1)
            if not re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*', name):
                raise ValueError(f"Invalid name: {name}")

            # Safely evaluate the expression
            try:
                value = ast.literal_eval(expr)
            except (SyntaxError, ValueError):
                value = compile(expr, '<string>', 'eval')

            namespace[name] = str(value)
            print(f"{name}={value}")
            sys.stderr.write(f"OK {name}={value}\n")
        except Exception as e:
            sys.stderr.write(f"ERROR line {i}: {str(e)}\n")
            sys.exit(1)

def main():
    if len(sys.argv) == 2 and sys.argv[1] == '--make-check':
        input_bytes = sys.stdin.buffer.read()
        salt = os.getenv('RECIPE_SALT', b'')
        check_hex = compute_check(input_bytes, salt)
        print(f"check={check_hex}")
    else:
        path = sys.argv[1]
        try:
            with open(path, 'rb') as f:
                content = f.read()
            check_line = content.splitlines()[0].strip()
            check_hex = parse_check_line(check_line)
            body_bytes = content[len(check_line) + 1:].strip()
            if not body_bytes:
                sys.exit(0)

            input_bytes = body_bytes.encode('utf-8')
            salt = os.getenv('RECIPE_SALT', b'')
            computed_check = compute_check(input_bytes, salt)

            if computed_check != check_hex:
                sys.stderr.write("ERROR: check mismatch\n")
                sys.exit(1)

            evaluate_body(body_bytes, salt)
        except Exception as e:
            sys.stderr.write(f"ERROR: {str(e)}\n")
            sys.exit(1)

if __name__ == "__main__":
    main()

import sys
import os
import argparse
import ast
import hashlib

def compute_check(input_bytes, salt):
    combined = input_bytes + salt.encode()
    return hashlib.sha256(combined).hexdigest().lower()

def evaluate_expression(expr_str, names):
    try:
        node = ast.parse(expr_str, mode='eval')
        if node.body:
            raise ValueError("Invalid expression")
        result = eval(node.body, {'__builtins__': None}, names)
        return str(result)
    except Exception as e:
        raise ValueError(f"Error evaluating expression: {str(e)}")

def process_file(path):
    with open(path, 'r') as f:
        first_line = f.readline().strip()
        if not first_line.startswith('check='):
            print("ERROR: Invalid file format", file=sys.stderr)
            sys.exit(1)

        check_hex = first_line.split('=')[1]
        body = f.read().strip()

    salt = os.getenv('RECIPE_SALT', '')
    if not salt:
        print("ERROR: RECIPE_SALT environment variable not set", file=sys.stderr)
        sys.exit(1)

    expected_check = compute_check(body.encode(), salt)
    if expected_check != check_hex:
        print("ERROR: check mismatch", file=sys.stderr)
        sys.exit(1)

    names = {}
    for line_num, line in enumerate(body.splitlines(), 1):
        if not line:
            continue
        try:
            parts = line.split('=', 1)
            if len(parts) != 2:
                raise ValueError("Invalid line format")
            name = parts[0].strip()
            expr = parts[1].strip()

            if not name or not isinstance(name, str) or not name[0].isalnum() or not all(c.isalnum() or c == '_' for c in name[1:]):
                raise ValueError("Invalid name format")

            value = evaluate_expression(expr, names)
            names[name] = value
            print(f"{name}={value}")
            print(f"OK {name}={value}", file=sys.stderr)
        except ValueError as e:
            print(f"ERROR line {line_num}: {str(e)}", file=sys.stderr)
            sys.exit(1)

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--make-check', action='store_true')
    parser.add_argument('path', nargs='?')
    args = parser.parse_args()

    if args.make_check:
        input_bytes = sys.stdin.buffer.read()
        salt = os.getenv('RECIPE_SALT', '')
        if not salt:
            print("ERROR: RECIPE_SALT environment variable not set", file=sys.stderr)
            sys.exit(1)
        print(f"check={compute_check(input_bytes, salt)}")
    else:
        process_file(args.path)

if __name__ == '__main__':
    main()

import sys
import os
import hashlib
import ast

def main():
    # Read input
    input_lines = sys.stdin.read().splitlines()
    if not input_lines:
        sys.exit(1)

    # Parse check
    check_line = input_lines[0]
    if not check_line.startswith('check='):
        sys.exit(1)
    check_hex = check_line.split('=', 1)[1].strip()
    if not all(c in '0123456789abcdef' for c in check_hex):
        sys.exit(1)

    # Read body and compute check
    body = b'\n'.join(input_lines[1:]).encode('utf-8')
    salt = os.getenv('RECIPE_SALT', b'')
    if not salt:
        sys.exit(1)
    computed_check = hashlib.sha256(body + salt).hexdigest()
    if computed_check != check_hex:
        print('ERROR: check mismatch', file=sys.stderr)
        sys.exit(1)

    # Process body lines
    namespace = {}
    for line_num, line in enumerate(input_lines[1:], 1):
        if not line.strip():
            continue
        try:
            parts = line.split('=', 1)
            if len(parts) != 2:
                raise ValueError(f"Invalid line format: '{line}'")
            name, expr = parts
            if not name or not expr:
                raise ValueError(f"Empty name or expression in line: '{line}'")
            if not (name[0].isalnum() or name[0] == '_') or not all(c.isalnum() or c == '_' for c in name[1:]):
                raise ValueError(f"Invalid name format: '{name}'")

            # Evaluate expression
            try:
                value = eval(expr, {}, namespace)
            except Exception as e:
                print(f'ERROR line {line_num}: {str(e)}', file=sys.stderr)
                sys.exit(1)

            # Store and print result
            namespace[name] = value
            print(f'{name}={value}')
            print(f'OK {name}={value}', file=sys.stderr)
        except Exception as e:
            print(f'ERROR line {line_num}: {str(e)}', file=sys.stderr)
            sys.exit(1)

    sys.exit(0)

if __name__ == '__main__':
    main()
